/**
 * The app's only content source: the SQLite database bundled as an asset
 * (assets/db/quran-grammar.db, generated by `npm run db:mobile`).
 *
 * Installation and versioning
 * - expo-sqlite can only open databases in its own directory, so the asset is copied there
 *   once, under a name that carries the content hash: quran-grammar-<sha256 prefix>.db.
 * - assets/db/quran-grammar.json (written by scripts/ensure-db.mjs next to the database) is
 *   bundled as JavaScript and carries the database's content_version.content_sha256.
 * - AsyncStorage remembers which file was installed and the content_sha256 read from it.
 *   On launch, if that record matches the bundled manifest, the installed copy is opened
 *   directly (no copy). Otherwise the asset is imported again (forceOverwrite), its
 *   content_version is checked, the record is updated and the previous copy deleted.
 * - Nothing is ever written to the content database: the connection is set to
 *   `PRAGMA query_only`, so content_version and the verification hash stay intact.
 */
import AsyncStorage from '@react-native-async-storage/async-storage';
import {
  deleteDatabaseAsync,
  importDatabaseFromAssetAsync,
  openDatabaseAsync,
  type SQLiteDatabase,
} from 'expo-sqlite';
import { createContentRepository, type CachedContentRepository } from './content-store';
import {
  MOBILE_DATABASE_SCHEMA_VERSION,
  readContentVersion,
  type ContentVersionRow,
  type SqlExecutor,
} from './queries';

// eslint-disable-next-line @typescript-eslint/no-require-imports
const databaseAsset: number = require('../../assets/db/quran-grammar.db');
// eslint-disable-next-line @typescript-eslint/no-require-imports
const manifest: unknown = require('../../assets/db/quran-grammar.json');

const installKey = 'quran-grammar.content-database';

type InstallRecord = { name: string; contentSha256: string };

function bundledSha(): string {
  const sha = (manifest as { contentSha256?: unknown } | null)?.contentSha256;
  if (typeof sha !== 'string' || !/^[0-9a-f]{64}$/.test(sha))
    throw new Error('The bundled content manifest is missing its content hash.');
  return sha;
}

async function readRecord(): Promise<InstallRecord | null> {
  try {
    const value: unknown = JSON.parse((await AsyncStorage.getItem(installKey)) ?? 'null');
    if (
      value &&
      typeof value === 'object' &&
      typeof (value as InstallRecord).name === 'string' &&
      typeof (value as InstallRecord).contentSha256 === 'string'
    )
      return value as InstallRecord;
  } catch {
    // Unreadable record: treat as not installed.
  }
  return null;
}

function executor(db: SQLiteDatabase): SqlExecutor {
  return {
    all: <T>(sql: string, params: readonly (string | number | null)[] = []) =>
      db.getAllAsync<T>(sql, params as (string | number | null)[]),
  };
}

/** Open an installed copy read-only and return its version row, or null if it is unusable. */
async function openInstalled(
  name: string,
): Promise<{ db: SQLiteDatabase; version: ContentVersionRow } | null> {
  let db: SQLiteDatabase | null = null;
  try {
    db = await openDatabaseAsync(name);
    await db.execAsync('PRAGMA query_only = ON');
    const version = await readContentVersion(executor(db));
    if (version?.database_schema_version === MOBILE_DATABASE_SCHEMA_VERSION)
      return { db, version };
  } catch {
    // Missing, partially copied or foreign file.
  }
  await db?.closeAsync().catch(() => undefined);
  return null;
}

async function installDatabase(): Promise<SQLiteDatabase> {
  const sha = bundledSha();
  const name = `quran-grammar-${sha.slice(0, 16)}.db`;
  const record = await readRecord();

  if (record?.name === name && record.contentSha256 === sha) {
    const installed = await openInstalled(name);
    if (installed?.version.content_sha256 === sha) return installed.db;
    await installed?.db.closeAsync().catch(() => undefined);
  }

  await importDatabaseFromAssetAsync(name, { assetId: databaseAsset, forceOverwrite: true });
  const imported = await openInstalled(name);
  if (!imported)
    throw new Error(
      `The bundled content database is not a schema v${MOBILE_DATABASE_SCHEMA_VERSION} database.`,
    );
  if (imported.version.content_sha256 !== sha)
    // The manifest is regenerated by scripts/ensure-db.mjs; a mismatch means the database
    // was rebuilt without it. The imported file is still a valid database, so use it.
    console.warn('Content database hash differs from assets/db/quran-grammar.json.');
  await AsyncStorage.setItem(
    installKey,
    JSON.stringify({ name, contentSha256: sha } satisfies InstallRecord),
  ).catch(() => undefined);
  if (record && record.name !== name) await deleteDatabaseAsync(record.name).catch(() => undefined);
  return imported.db;
}

let repository: Promise<CachedContentRepository> | null = null;
let resolved: CachedContentRepository | null = null;

/** Singleton: installs (if needed) and opens the content database once per app process. */
export function getRepository(): Promise<CachedContentRepository> {
  if (!repository) {
    repository = installDatabase().then(
      (db) => {
        resolved = createContentRepository(executor(db));
        return resolved;
      },
      (error: unknown) => {
        // Allow a retry to attempt the installation again.
        repository = null;
        throw error;
      },
    );
  }
  return repository;
}

/** The repository if it has already opened; lets screens read cached content synchronously. */
export function getOpenedRepository(): CachedContentRepository | null {
  return resolved;
}
